"""Build the linked, dependency-free HTML research atlas from this editorial source."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent
REFS = {r['id']: r for r in json.loads((ROOT / 'assets/references/manifest.json').read_text())}
SOURCES = [
    ('S01', 'Mites as miniature animals', 'USDA/IDtools — Oribatida identification guide', 'https://idtools.org/id/invasive_mite/Invasive_Mite_Identification/key/Major_Mite_taxa/Media/Html/Oribatida.htm', 'Institutional identification resource. Armored moss-mite morphology and distinctions from other mite groups. Does not imply all mites have the same diet.'),
    ('S02', 'Water-film animals', 'Lucid identification key — Tardigrada', 'https://keys.lucidcentral.org/keys/v3/mites/Invasive_Mite_Identification/key/Is_it_a_mite/Media/Html/TardiM.htm', 'Identification resource: normal adult size, unjointed legs, wet habitats and inactive dry stages. Its common adult interval is 0.25–0.5 mm; reported extremes extend beyond it.'),
    ('S03', 'Dormancy', 'American Museum of Natural History — Tardigrade', 'https://www.amnh.org/explore/ology/ology-cards/364-tardigrade', 'Museum explanation of water loss and survival. Supports dormancy as a state change; does not support invulnerability during active movement.'),
    ('S04', 'Amoeba dimensions and morphology', 'NIES — Amoeba morphology database', 'https://www.nies.go.jp/chiiki1/protoz/morpho/flagella/amoeba.htm', 'Institutional species descriptions with underlying references. Amoeba proteus can reach about 600 µm or more. Historical taxonomy and species identifications need care.'),
    ('S05', 'Engulfing prey', 'Jeon & Jeon (1976) — SEM observations of Amoeba proteus during phagocytosis', 'https://pubmed.ncbi.nlm.nih.gov/1271309/', 'Primary research, Journal of Protozoology. Substrate attachment and broad pseudopods forming a food cup. DOI: 10.1111/j.1550-7408.1976.tb05249.x.'),
    ('S06', 'Amoeboid locomotion', 'De la Fuente et al. (2019) — Evidence of conditioned behavior in amoebae', 'https://www.nature.com/articles/s41467-019-11677-w', 'Primary research. Consulted for pseudopodia, cytoplasmic streaming and response to chemical/physical cues; the atlas does not extrapolate human-like intelligence from the behavioral experiments.'),
    ('S07', 'Paramecium dimensions', 'Martin Kreutz — Paramecium caudatum, Real Micro Life', 'https://realmicrolife.com/paramecium-caudatum/', 'Firsthand illustrated observations, including measured 200–260 µm cells. A population observation, not a universal size interval for all Paramecium species.'),
    ('S08', 'Ciliary escape', 'Ogura & Takahashi (1976) — Artificial deciliation causes loss of calcium-dependent responses in Paramecium', 'https://www.nature.com/articles/264170a0', 'Primary experimental report: obstacle-triggered ciliary reversal. DOI: 10.1038/264170a0.'),
    ('S09', 'Short-range defensive propulsion', 'Knoll, Haacke-Bell & Plattner (1991) — Local trichocyst exocytosis provides an efficient escape mechanism', 'https://pubmed.ncbi.nlm.nih.gov/23194850/', 'Primary study of Paramecium escaping predatory Dileptus through local discharge. Supports an escape response rather than ranged projectile combat.'),
    ('S10', 'Attached ciliates', 'NIES — Vorticella morphology database', 'https://www.nies.go.jp/chiiki1/protoz/morpho/ciliopho/vorticel.htm', 'Institutional descriptions; body and stalk lengths are distinct measurements. Different populations and cited studies report different size intervals.'),
    ('S11', 'Contractile stalk mechanics', 'Upadhyaya et al. (2008) — Power-Limited Contraction Dynamics of Vorticella convallaria', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC2134882/', 'Primary biophysical study of rapid stalk contraction. Supports a fast retract/slow return contrast, with substrate attachment essential.'),
    ('S12', 'Small flagellate size', 'Podwin, Kubicki & Dziuban (2017) — Study of the behavior of Euglena viridis, Euglena gracilis and Lepadella patella cultured in all-glass microaquarium', 'https://link.springer.com/article/10.1007/s10544-017-0205-0', 'Primary microaquarium study: typical E. gracilis length 35–50 µm and E. viridis 40–65 µm. DOI: 10.1007/s10544-017-0205-0.'),
    ('S13', 'Following light', 'Giometto et al. (2015) — Generalized receptor law governs phototaxis in Euglena gracilis', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4460502/', 'Primary controlled-light experiments. Light-response apparatus and preferred light intensity; positive and negative phototaxis depend on conditions.'),
    ('S14', 'Diatom traction', 'Bondoc et al. (2016) — Selective silicate-directed motility in diatoms', 'https://www.nature.com/articles/ncomms10540', 'Primary study of a biofilm-forming pennate diatom. Raphe-associated secretion and substrate gliding are species-specific; not all diatoms glide.'),
    ('S15', 'Microscale fluid mechanics', 'Lauga & Powers (2009) — The hydrodynamics of swimming microorganisms', 'https://www.damtp.cam.ac.uk/user/lauga/papers/32.pdf', 'Research review, Reports on Progress in Physics 72, 096601. Viscous dominance, reciprocal motion and swimming mechanics. DOI: 10.1088/0034-4885/72/9/096601.'),
    ('S16', 'Biofilm heterogeneity', 'Jo, Price-Whelan & Dietrich (2022) — Gradients and consequences of heterogeneity in biofilms', 'https://www.nature.com/articles/s41579-022-00692-2', 'Research review of resource gradients and spatially differentiated microbial assemblages. Specific oxygen and nutrient fields require habitat measurements.'),
    ('S17', 'Optical resolution', 'Nikon MicroscopyU — Numerical Aperture', 'https://www.microscopyu.com/microscopy-basics/numerical-aperture', 'Instrument-maker technical reference: NA governs resolving power and light collection. Zoom alone cannot create new structural detail.'),
    ('S18', 'Focus', 'Nikon MicroscopyU — Depth of Field and Depth of Focus', 'https://www.microscopyu.com/microscopy-basics/depth-of-field-and-depth-of-focus', 'Technical reference showing rapid loss of specimen depth of field with increasing numerical aperture; values depend on the optical system.'),
    ('S19', 'DIC appearance', 'Nikon MicroscopyU — Differential Interference Contrast', 'https://www.microscopyu.com/techniques/dic', 'Technical reference: directional contrast comes from optical-path gradients. The apparent relief is not a direct topographic height map.'),
    ('S20', 'SEM preparation', 'James Cook University — Scanning Electron Microscope sample requirements', 'https://www.jcu.edu.au/advanced-analytical-centre/analytical-facilities/sample-requirements/scanning-electron-microscope', 'Facility guidance: conventional high-vacuum SEM requires stable dry specimens, often with conductive coating.'),
    ('S21', 'Cryo and environmental exceptions', 'Weizmann Institute — Cryo SEM, life science', 'https://www.weizmann.ac.il/ChemicalResearchSupport/units/electron-microscopy/methods/cryo-sem-life-science', 'Facility explanation of frozen hydrated samples, possible preparation artifacts and the environmental-SEM exception. Does not make conventional SEM a live underwater camera.'),
    ('S22', 'TEM as a section', 'Richard Allen — Paramecium caudatum, CIL:36755', 'https://ccdb.ucsd.edu/images/36755', 'Primary microscopy dataset: fixed, resin-embedded, approximately 75 nm sections. Supports an ultrastructure reference distinct from a whole-organism environment.'),
    ('S24', 'Physical field size', 'Nikon MicroscopyU — Field of View', 'https://www.microscopyu.com/microscopy-basics/field-of-view', 'Technical reference for field number divided by objective magnification. FN18 is an explicit illustrative assumption; camera crops and auxiliary optics change the field.'),
    ('S23', 'Feeding diversity', 'Potapov et al. (2022) — Feeding habits and multifunctional classification of soil-associated consumers', 'https://doi.org/10.1111/brv.12832', 'Research synthesis across soil food webs, including mites, protists and rotifers. Useful caution against treating every small animal as a predator.'),
]


def esc(value):
    return html.escape(str(value), quote=True)


def cite(*ids):
    return ' <span class="cite">' + ' · '.join(f'<a href="sources.html#{i}">[{i}]</a>' for i in ids) + '</span>'


def section(title, body, ident=''):
    return f'<section class="section"{f" id={esc(ident)}" if ident else ""}><h2>{title}</h2>{body}</section>'


def table(headers, rows, caption):
    return '<div class="table-wrap"><table><caption>' + caption + '</caption><thead><tr>' + ''.join(f'<th scope="col">{h}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in row) + '</tr>' for row in rows) + '</tbody></table></div>'


def ref(ident):
    r = REFS[ident]
    license_url = r['license_url'] or ('https://creativecommons.org/publicdomain/zero/1.0/' if r['license'] == 'CC0' else 'https://commons.wikimedia.org/wiki/Commons:Public_domain')
    return f'''<figure class="ref" id="ref-{ident}"><a href="{esc(r['local'])}" aria-label="Open full reference: {esc(r['title'])}"><img src="{esc(r['local'])}" alt="{esc(r['note'])}" loading="lazy"></a><figcaption><strong>{esc(r['title'])}</strong>{esc(r['note'])}<span class="credits">{esc(r['author'])} · <a href="{esc(license_url)}">{esc(r['license'])}</a> · <a href="{esc(r['source'])}">Source &amp; original</a><br>{esc(r['modification'])}</span></figcaption></figure>'''


def refs(*ids):
    return '<div class="refs">' + ''.join(ref(i) for i in ids) + '</div>'


def concept(name, labels, note):
    path = f'assets/concepts/{name}.webp'
    return f'''<figure class="triptych"><a href="{path}"><img src="{path}" alt="Generated concept board: {esc('; '.join(labels))}. {esc(note)}" loading="lazy"></a><figcaption><div class="panel-labels">{''.join(f'<div><strong>{i+1:02d} / {label}</strong><span>Visual possibility</span></div>' for i,label in enumerate(labels))}</div><span class="tag idea">AI concept art · not microscopy evidence</span><p>{note}</p><p class="meta">Generated with the built-in image_gen tool, 30 October 2026. Composition and field widths are illustrative, not calibrated. Click to enlarge. <a href="assets/concepts/prompts.json">Prompt set</a> · <a href="visual-styles.html#art-caveats">Read the visual accuracy notes</a>.</p></figcaption></figure>'''


NAV = [('index.html', 'Overview'), ('01-mites.html', '01 Mites'), ('02-waterfilm.html', '02 Water films'), ('03-protists.html', '03 Protists'), ('04-cells.html', '04 Small cells'), ('environments.html', 'Habitats'), ('visual-styles.html', 'Visual styles'), ('powers.html', 'Powers & dynamics'), ('sources.html', 'Sources')]


def page(filename, title, kicker, lede, body, prev=None, next_page=None):
    nav = ''.join(f'<a href="{url}"{chr(32)+"aria-current=page" if url==filename else ""}>{label}</a>' for url,label in NAV)
    sequence = '<div class="next">' + (f'<a href="{prev[0]}">← {prev[1]}</a>' if prev else '<a href="index.html">← Research overview</a>') + (f'<a href="{next_page[0]}">{next_page[1]} →</a>' if next_page else '<a href="sources.html">Sources &amp; image credits →</a>') + '</div>'
    output = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(lede)}"><title>{esc(html.unescape(title))} · Micro / Research</title><link rel="stylesheet" href="styles.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="masthead"><div class="wrap"><a class="brand" href="index.html"><b>µ</b> MICRO / RESEARCH</a><nav aria-label="Research collection">{nav}</nav></div></header><main class="wrap" id="main"><div class="intro"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p class="lede">{lede}</p><p class="meta">Field notes / 30 October 2026 · Biology, visual references &amp; possibilities for simulation</p></div>{body}{sequence}</main><footer class="footer"><div class="wrap"><p>A research atlas, not a game specification. Observations are cited; proposed interactions and render treatments are interpretations. Body lengths are approximate and species-dependent. All reference images are local, with individual credits. <a href="sources.html">Evidence &amp; rights</a> · <a href="assets/references/manifest.json">Image manifest</a></p></div></footer></body></html>'''
    (ROOT / filename).write_text(output + '\n')


def specs(size, optics, field):
    return f'<dl class="specs"><div><dt>Representative body size</dt><dd>{size}</dd></div><div><dt>Useful observing range</dt><dd>{optics}</dd></div><div><dt>Illustrative field width</dt><dd>{field}</dd></div></dl>'


def callout(title, text):
    return f'<aside class="callout"><span class="eyebrow">{title}</span><p>{text}</p></aside>'


def build_index():
    body = '''<figure class="hero"><img src="assets/concepts/03-protist-garden.webp" alt="Three generated visions of a microscopic community: brightfield overhead, immersive 3D, and darkfield"><figcaption>One world, different instruments. Generated visual research, not a photograph: an amoeba, ciliate, attached feeder and algal scaffold. <a href="03-protists.html#concept">Inspect the board →</a></figcaption></figure><div class="stats"><div class="stat"><b>4</b>overlapping scale bands</div><div class="stat"><b>12</b>credited web references</div><div class="stat"><b>4 × 3</b>concept-art views</div><div class="stat"><b>2D / 3D</b>possibilities throughout</div></div>'''
    body += section('A world changes as the field narrows.', '<div class="split"><div><p>A moss cushion can read as a landscape of leaves and mineral grains. Within its moisture, a tardigrade grips a surface. Narrow the field again and a ciliate becomes a fast moving body beside a slow, reshaping amoeba. At still smaller fields, individual algal cells and a biofilm become the environment.</p><p>These are overlapping views, not a biological ladder. <strong>A large single cell can rival or exceed a small animal in length.</strong> “Protozoan” is used here as an informal historical term for animal-like protists, not a single modern lineage.</p></div><div class="card"><span class="eyebrow">Reading key</span><p><span class="tag">Observed biology</span> Described traits with linked evidence.</p><p><span class="tag idea">Gameplay possibility</span> A possible translation of a trait; no chosen rules, progression, economy or game loop.</p><p><span class="tag idea">AI concept art</span> Visual hypotheses. Use real images for morphology and scale.</p></div></div>')
    bands = [
        ('01', '01-mites.html', 'Moss &amp; litter frontier', '01-moss-frontier', 'Mites · roughly 0.2–1 mm selected bodies', '10–40× stereo · a few millimetres across', 'Jointed legs, armor, humidity pockets and difficult terrain.'),
        ('02', '02-waterfilm.html', 'The water-film world', '02-waterfilm', 'Tardigrades &amp; rotifers · roughly 0.1–0.5 mm', '40–100× compound · 4.5–1.8 mm field', 'Claw grip, attachment, filtering and the cost of drying.'),
        ('03', '03-protists.html', 'A garden of large cells', '03-protist-garden', 'Amoebae &amp; ciliates · tens to hundreds of µm', '100–200× compound · 1.8–0.9 mm field', 'Shape change, ciliary motion, engulfing and contractile stalks.'),
        ('04', '04-cells.html', 'The small-cell neighborhood', '04-cell-neighborhood', 'Small flagellates &amp; diatoms · roughly 10–80 µm selected bodies', '400× compound · 450 µm field; oil detail optional', 'Light response, surface gliding, gradients and bacterial prey patches.'),
    ]
    cards = '<div class="grid">' + ''.join(f'<article class="card"><a href="{url}"><img src="assets/concepts/{art}.webp" alt="Generated comparison board for {esc(title)}" loading="lazy"></a><span class="number">{n}</span><h3><a href="{url}">{title}</a></h3><p>{size}<br><span class="meta">{optics}</span></p><p>{desc}</p></article>' for n,url,title,art,size,optics,desc in bands) + '</div>'
    body += section('Browse from larger to smaller.', cards, 'bands')
    body += section('Magnification needs a physical ruler.', '''<p>A screen enlargement is not an optical measurement. For the compound-microscope examples here, assume a <strong>10× eyepiece and field number 18 mm</strong>, with no additional camera crop: total magnification = eyepiece × objective; specimen field diameter ≈ 18 mm ÷ objective magnification. These illustrative instrument assumptions are not measurements of the imported images. <a class="cite" href="sources.html#S24">[S24]</a></p>''' + table(['Objective', 'Total visual magnification', 'Illustrative field diameter', 'What fits'], [
        ('4×', '40×', '4.5 mm', 'A small-animal neighborhood'), ('10×', '100×', '1.8 mm', 'Whole tardigrades and large cells'), ('20×', '200×', '0.9 mm', 'A few large protists'), ('40×', '400×', '450 µm', 'Small cells; a large amoeba may crop'), ('100× oil', '1000×', '180 µm', 'Cell detail; larger bodies crop')
    ], 'Field diameter under the stated FN18 assumption; magnification does not guarantee resolution.') + '<p>Numerical aperture and wavelength limit detail; increasing display zoom does not reveal an otherwise unresolved flagellum or membrane. Higher-NA objectives also narrow the focus zone.' + cite('S17','S18') + '</p>' + '''<div class="ruler"><h3>How much of one cell fits?</h3><label for="objective">Illustrative objective: <output id="mag">10× objective · 100× total</output></label><input id="objective" type="range" min="0" max="4" step="1" value="1" aria-describedby="field-note"><div id="field-note" class="meta" aria-live="polite">FN18 field diameter: 1.80 mm. A 200 µm ciliate spans 11% of the field.</div><div class="ruler-track" aria-hidden="true"><div class="ruler-cell" id="cell" style="width:11.11%"></div><span class="ruler-cell-label">Illustrative 200 µm cell · one field across this line</span></div><p class="meta">This is a proportional ruler, not a biological simulation. Stereo microscopes use a different optical arrangement and are excluded.</p><noscript><p class="no-js">Interactive ruler requires JavaScript; the complete field-size table above remains available.</p></noscript></div><script>const o=document.getElementById('objective');function update(){const a=[4,10,20,40,100][Number(o.value)],f=18000/a,p=200/f*100;document.getElementById('mag').textContent=a+'×'+(a===100?' oil':'')+' objective · '+a*10+'× total';document.getElementById('field-note').textContent='FN18 field diameter: '+(f>=1000?(f/1000).toFixed(2)+' mm':f+' µm')+'. A 200 µm ciliate spans '+Math.round(p)+'% of the field'+(p>100?' and would be cropped.':'.');document.getElementById('cell').style.width=p+'%';}o.addEventListener('input',update);update();</script>''', 'magnification')
    body += section('Three questions to keep open.', '<div class="grid three"><article class="card"><h3>What does “real” mean?</h3><p>An optical image, a hypothetical viewpoint within the water, and an SEM-style surface view reveal different information.</p><a class="inline-link" href="visual-styles.html">Compare visual treatments →</a></article><article class="card"><h3>What can biology do?</h3><p>Engulfing, gliding, retracting, sensing and dormancy already offer striking interactions with meaningful constraints.</p><a class="inline-link" href="powers.html">Explore powers &amp; dynamics →</a></article><article class="card"><h3>Where can life meet?</h3><p>Moss films, pond margins and biofilms differ in chemistry, connectivity and community. Scale alone does not establish coexistence.</p><a class="inline-link" href="environments.html">Explore the environments →</a></article></div>')
    page('index.html', 'Worlds within a drop.', 'Micro / Research atlas · 01—04', 'A visual and biological reference collection for realistic microscopic simulation—from mites among moss leaves to single cells moving through a biofilm.', body, next_page=('01-mites.html','Begin with mites'))


def build_mites():
    body = specs('Selected small mites: ~0.2–1 mm', '10–40× stereo; 40–100× for details', 'About 2–10 mm; optics-dependent')
    body += callout('Scale is an editorial grouping', 'Mites are multicellular arachnids, and many are visible as tiny moving dots. This band emphasizes small soil and moss mites; it does not include every mite species. The 0.2–1 mm interval is a working visual bracket, not a taxonomic limit.')
    body += section('Small enough for moss to become terrain.', '<p>Armored oribatid mites supply hard, rounded silhouettes, bristles and jointed legs that differ markedly from soft water-film animals. The source identification key distinguishes armored forms by more than shell shape; identification from a pretty photograph alone remains uncertain.' + cite('S01') + '</p><p>A plausible scene has interlocking leaf edges, decomposing plant matter, hyphae and mineral grains. Selected moss or litter mites can belong here, but a predatory mite, a fungal grazer and a plant feeder imply different interactions. Diet must be attached to an identified species rather than to “mite” as a category.' + cite('S23') + '</p>' + refs('mite','moss'))
    body += section('Biological affordances worth studying.', table(['Trait / evidence', 'Possible interaction', 'Constraint to retain'], [
        ('Articulated legs and claws', 'Choosing purchase across leaf edges and loose particles.', 'Body clearance, reach and attachment matter; a smooth wet meniscus is a different obstacle from dry litter.'),
        ('Sclerotized cuticle in armored forms', 'A protected body that can push through abrasive gaps.', 'Armor shape can obstruct access to narrow spaces; it does not confer immunity.'),
        ('Species-specific feeding roles', 'Selective grazing or searching among microbial patches.', 'Do not combine all feeding modes into one animal without labeling the departure.'),
        ('Heterogeneous moisture', 'Seeking humid refuges while habitat connections change.', 'Humidity tolerance and immersion tolerance need species-level evidence; do not make a terrestrial mite an indefinite underwater swimmer.')
    ], 'Observed morphology and habitat knowledge motivate these speculative interactions; they do not prescribe mechanics.'))
    body += section('Two spatial readings.', '<div class="split"><article><span class="tag idea">2D possibility</span><h3>A surface route map</h3><p>An overhead stereo-like view makes gaps, feet and leaf edges legible. Modest height layers could represent overlapping leaves; explicit overlap shadows would help distinguish a bridge from a wall.</p><p>Use the environment for scale: a 0.6 mm animal is only a fraction of a several-millimetre field. Individual bacteria should not become visible inhabitants in this view.</p></article><article><span class="tag idea">3D possibility</span><h3>A humid litter canyon</h3><p>An oblique view can emphasize load-bearing surfaces and the animal’s clearance. Uneven contact and leg placement would contribute more to realism than a camera that treats every particle as a rock cliff.</p><p>Restrained reflected daylight is appropriate outside water. Specular wet patches can indicate a surface transition, but luminous mushrooms and distant atmospheric fog would be artistic choices.</p></article></div>')
    body += section('Concept board / moss frontier.', concept('01-moss-frontier', ['2D stereo-like view','3D plausible daylight','3D SEM-inspired surface'], 'A selected 0.6 mm mite in an approximately 4 mm-wide scene is the intended scale anchor. The first panel blends transmitted-looking clarity with reflected specimen detail; a true stereo reference should guide the final optics. The middle panel explores navigable litter. The last borrows electron-image texture, not literal natural lighting.'), 'concept')
    body += section('Reference questions before a simulation.', '<p>Choose a species and verify its adult dimensions, feeding apparatus, normal gait, humidity range and response to standing water. The moss reference is a light-microscope leaf image: it documents cell architecture, not the appearance of an entire forest from the mite’s height. Use the <a href="02-waterfilm.html">next band</a> to investigate the moisture layer rather than assuming the same locomotion simply shrinks.</p>')
    page('01-mites.html','Moss &amp; litter frontier.','Scale band 01 · millimetre neighborhoods','Mites make the boundary between a tiny landscape and a microscopic habitat tangible: armor, jointed movement and organic terrain.',body,('index.html','Overview'),('02-waterfilm.html','Enter the water film'))


def build_waterfilm():
    body = specs('Tardigrades commonly ~250–500 µm', '40–100× total; 200–400× for detail', '4.5–1.8 mm at FN18 / 4–10× objectives')
    body += section('A thin wet habitat, not a tiny ocean.', '<p>Tardigrades have four pairs of unjointed lobopod legs with claws. Many active moss dwellers need a water film; their dry inactive state is biologically different. Feeding varies among species, including grazing and predation. A typical adult size is only a guide: the wider reported range is much larger.' + cite('S02') + '</p><p>Rotifers add a different silhouette: an extensible body, an anchoring foot in many forms, and a ciliated feeding crown. A crown creates transport of small particles; it is not a pair of rotating saw blades. The selected <i>Philodina</i> reference is a bdelloid rotifer; other rotifers can feed or move differently.' + cite('S23') + '</p>' + refs('tardigrade-light','tardigrade-sem','rotifer','moss'))
    body += section('Capabilities with a biological price.', table(['Observed basis', 'Gameplay possibility', 'Boundary'], [
        ('Tardigrade claws and short legs', 'Deliberate purchase on a leaf cell wall or detrital ridge.', 'Claws need reachable substrate; this is not a fast open-water predator.'),
        ('Dormancy during water loss', 'A time/state transition as a wet route disappears, followed by uncertain rehydration.', 'Inactivity is the central cost. Avoid an invulnerability button that keeps normal movement and feeding.'),
        ('Rotifer feeding currents', 'Choosing attachment sites that intercept suspended food.', 'Particles must be the right kind and size; currents and attachment depend on local geometry.'),
        ('Extensible bodies and anchor points', 'Alternating between holding, extending and relocating.', 'Different animals require different movement models; no universal “micro-animal” rig.')
    ], 'Proposed dynamics are interpretations of anatomy, feeding and water dependence.') + '<p>The museum’s dormancy account is a useful antidote to the “indestructible water bear” trope. Survival under an experimental condition does not imply an active animal can behave normally there.' + cite('S03') + '</p>')
    body += section('2D and 3D reveal different constraints.', '<div class="split"><article><span class="tag idea">2D possibility</span><h3>The wet mount</h3><p>A mostly planar brightfield or DIC view can reveal feet, gut contents and leaf cells. Water-film thickness can vary across the surface; a narrowing connection can isolate a patch without turning the world into a side-scrolling aquarium.</p><p>A coverslip is a real constraint if this is a laboratory sample: compression and reduced vertical freedom should be acknowledged.</p></article><article><span class="tag idea">3D possibility</span><h3>Between a leaf and an interface</h3><p>Use leaf ridges and film thickness to create a shallow but real volume. A 300 µm body cannot occupy a water gap much thinner than its own thickness without deformation or exposure.</p><p>Menisci can define the boundary. They should not be a collection of giant free-standing bubbles. Immersive camera lighting is an interpretation, not what a light microscope directly records.</p></article></div>')
    body += section('Concept board / water-film world.', concept('02-waterfilm', ['2D DIC-inspired wet mount','3D hypothetical water-film view','3D SEM-inspired specimen'], 'The intended neighborhood spans about 1.5 mm, with a 350 µm tardigrade as the anchor. DIC edge relief is optical contrast, not proof of surface height. The rendered middle panel exaggerates transparency and meniscus highlights for legibility. The SEM-inspired panel treats surfaces as prepared and opaque; suspended live behavior in that look would be an explicit fiction. Generated leg placement is not an anatomy reference: retain exactly four leg pairs in any model.'), 'concept')
    body += section('What is still uncertain?', '<p>Cryptobiosis tolerance, preparation time, recovery and feeding preference are species-dependent. The SEM reference represents an animal prepared from an active state, not a living animal walking in a high-vacuum microscope. Use the real micrograph for cuticle and claw reference; use filmed living specimens for gait. Compare <a href="visual-styles.html#electron">electron imaging</a> before adopting its look.</p>')
    page('02-waterfilm.html','The water-film world.','Scale band 02 · micro-animals','Tardigrades and rotifers make hydration, attachment and particle transport visible at the boundary between terrain and fluid.',body,('01-mites.html','Mites'),('03-protists.html','Explore large single cells'))


def build_protists():
    body = specs('Selected bodies: ~40–600+ µm', '100–200× total; 400× for details', '1.8–0.9 mm at FN18 / 10–20× objectives')
    body += section('A single cell can be a whole creature.', '<p><i>Amoeba proteus</i> changes outline through broad pseudopods and internal streaming. It can reach roughly 600 µm or more, so an amoeba does not automatically belong “below” a tardigrade in size. The working art reference is a few hundred micrometres across, with a clear edge and granular interior.' + cite('S04','S06') + '</p><p><i>Paramecium caudatum</i> supplies a more stable, slipper-shaped body and coordinated ciliary motion. Measured examples in the cited observer’s population are around 200–260 µm long. <i>Vorticella</i> is a smaller attached ciliate with a bell-like body and a contractile stalk: measure the body separately from the whole extended structure.' + cite('S07','S10') + '</p>' + refs('amoeba','paramecium','vorticella','spirogyra'))
    body += section('Three very different kinds of agency.', table(['Organism / trait', 'Possible power or dynamic', 'What makes it convincing'], [
        ('Amoeba / pseudopod extension', 'Branching reach, changing contact area and fitting around obstacles.', 'Approximate conservation of body volume; no limb appears without withdrawing material elsewhere.'),
        ('Amoeba / phagocytosis', 'Surrounding an edible target and keeping contact while a food cup closes.', 'Capture requires adhesion and suitable size; visible digestion should take time, with any compression labeled.'),
        ('Paramecium / ciliary reversal', 'A brief reverse-and-reorient escape when encountering an obstacle.', 'An organized change in ciliary beating, not coasting backwards from inertia.'),
        ('Paramecium / trichocysts', 'Short-range defensive displacement away from an attack.', 'Local discharge has experimental support; repeated ranged shooting and infinite ammunition do not follow from it.'),
        ('Vorticella / contracting stalk', 'Abrupt retreat toward an anchor, then reopening its feeding position.', 'The anchor remains fixed; the stalk coils rather than turning into a free grappling rope.')
    ], 'Interaction vocabulary; every proposed use remains optional.') + '<p>Food-cup formation, ciliary reversal, local defensive discharge and fast stalk contraction have separate experimental support. They should remain distinct mechanisms instead of cosmetic variants of a dash.' + cite('S05','S08','S09','S11') + '</p>')
    body += section('The substrate is part of the organism’s behavior.', '<div class="split"><article><span class="tag idea">2D possibility</span><h3>Readable interactions in a thin slice</h3><p>A brightfield overhead view could make membrane contact, engulfing geometry and attached feeding obvious. A shallow volume or several focal layers would retain the possibility of one cell passing above another.</p><p>Substrate-bound amoeboid crawling should read differently from a ciliate swimming through the same field. Repositioning a focal plane is an observation choice, not an ability of the organism.</p></article><article><span class="tag idea">3D possibility</span><h3>A transparent, crowded volume</h3><p>Soft bodies can deform around detritus while ciliates follow curved paths between filaments. Most cytoplasm should remain weakly contrasting; silhouette, internal granules and occlusion can carry form without opaque monster skin.</p><p>Detailed cilia may need visual aggregation at distance. The habitat needs background surfaces and particles without filling every cubic micrometre with equally sharp debris.</p></article></div>')
    body += section('Concept board / protist garden.', concept('03-protist-garden', ['2D brightfield-inspired','3D hypothetical immersion','2D darkfield-inspired'], 'Intended field width is approximately 0.9 mm. The board pairs a roughly 300 µm amoeba and 180 µm ciliate with an attached feeder and algal filament. Exact sizes and simultaneous co-occurrence are unverified. Darkfield bright edges represent scattered illumination, not self-emission. The 3D panel is a rendering hypothesis; it is not reconstructed microscopy.'), 'concept')
    body += section('Do not confuse being single-celled with being simple.', '<p>Motion, digestion, shape, sensing and osmoregulation happen within one body. A pulsating contractile vacuole can make physiology visible; it is not a heart or a propulsion jet. Binary fission would be a long-timescale biological event, not evidence that a cell can spawn an instant combat clone. Chemical sensing may be represented through a separate explanatory overlay, clearly identified as data rather than visible colored water.</p><p>See <a href="powers.html">powers and dynamics</a> for tradeoffs and <a href="04-cells.html">small cells</a> for a different balance of surface attachment, light and gradients.</p>')
    page('03-protists.html','A garden of large cells.','Scale band 03 · amoebae & ciliates','An amoeba flows, a ciliate reverses, an attached feeder retracts. Their contrasts offer a rich biological vocabulary without inventing magic.',body,('02-waterfilm.html','Water-film animals'),('04-cells.html','Narrow to small cells'))


def build_cells():
    body = specs('Selected small protists: ~10–80 µm', '400× total; optional 1000× oil detail', '450 µm; 180 µm at FN18 / 100× oil')
    body += section('Small cells, large surroundings.', '<p><i>Euglena gracilis</i> is a useful anchor: the cited microaquarium study gives typical lengths of 35–50 µm. Other euglenids can be substantially larger. Here a 45 µm cell moves past a surface film, with selected tens-of-micrometres diatoms as rigid geometric neighbors.' + cite('S12') + '</p><p>Phototaxis in <i>E. gracilis</i> depends on its light-sensing apparatus and illumination conditions. Its red stigma works with a photoreceptor; it is not an image-forming eye. Responses can favor or avoid light depending on intensity. This suggests sensing and orientation, rather than a permanent “go toward the brightest thing” behavior.' + cite('S13') + '</p>' + refs('euglena','diatoms','biofilm-sem','spirogyra'))
    body += callout('Reference context matters', 'The diatom photograph is from Antarctic marine sea ice, and the biofilm SEM is from marine seagrass. They are useful morphology and texture analogues. They are not documentation of the same freshwater community as Euglena or the moss animals.')
    body += section('Surface worlds and sensory fields.', table(['Biological basis', 'Possible dynamic', 'Constraint / uncertainty'], [
        ('Flagellar locomotion', 'Orientation-dependent propulsion, curved paths and local steering.', 'A flagellum is thin; full visible detail at all distances would exceed ordinary optical resolution.'),
        ('Light response in Euglena', 'Seeking an appropriate illuminated patch and leaving excessive exposure.', 'The red spot does not confer a tiny human camera or omniscient detection.'),
        ('Gliding in selected raphid diatoms', 'Following contact geometry and switching a route across an attached surface.', 'Not every diatom is motile; gliding depends on the raphe and substrate interaction.'),
        ('Biofilm resource gradients', 'Accessing richer exposed zones versus sheltered, depleted interiors.', 'Oxygen, nutrients and toxins are separate fields; exact profiles require data.'),
        ('Smaller bacterial cells and particles', 'Fine food patches or surface colonization rather than large monsters.', 'Use ~1–5 µm only as an illustrative common bacterial bracket, not a universal size rule. Viruses and molecules are outside this atlas’s creature scale.')
    ], 'Speculative interactions informed by the cited flagellate, diatom and biofilm studies.') + '<p>Research on a biofilm-forming pennate diatom supports contact-based gliding, while biofilm studies show why local chemistry can vary within one apparent patch. Neither establishes a universal movement rule or chemistry for all microbial habitats.' + cite('S14','S16') + '</p>')
    body += section('How to make both 2D and 3D informative.', '<div class="split"><article><span class="tag idea">2D possibility</span><h3>A field of cells and trajectories</h3><p>At 400× total magnification, a 45 µm cell occupies about one tenth of a 450 µm field. Phase contrast can emphasize transparent cells, with halos identified as imaging artifacts. A fixed surface layer is natural for exploring diatom traction and biofilm contact.</p><p>Bacteria should remain small dots or rods; do not give each a legible fantasy face. Brownian motion is more important for small particles than for an entire large protist.</p></article><article><span class="tag idea">3D possibility</span><h3>A surface with a shallow sky of water</h3><p>Use a few cell lengths of volume above a matrix-coated surface. Rigid silica shells, softer cells and sparse debris give material contrast. Avoid a limitless ocean with a tiny reef rescaled into it.</p><p>Scattering, refraction and biological pigments could guide a physically motivated rendering, but optical diffraction and camera resolution still matter. A hypothetical microscopic camera is not a camera that could literally fit beside these cells.</p></article></div>')
    body += section('Concept board / small-cell neighborhood.', concept('04-cell-neighborhood', ['2D phase-contrast-inspired','3D hypothetical illumination','3D SEM-inspired surface'], 'Intended field width is about 180 µm with a roughly 45 µm flagellate, closer to the optional oil-detail field than the default 400× survey. Internal features and thin flagella are deliberately enhanced. The SEM-inspired panel emphasizes dry, opaque surface detail and does not reproduce a live hydrated biofilm. Shell pores and fine bacterial texture require resolution checks before being treated as observable features.'), 'concept')
    body += section('Where this collection stops.', '<p>A closer study could enter ultrastructure, organelles and molecular processes, but that is a different environment and time scale. Ordinary light microscopy cannot resolve a lipid bilayer as a pair of distinct physical surfaces. TEM sections reveal internal structure through preparation, not a navigable miniature room inside a living cell.' + cite('S17','S22') + '</p><p>Compare <a href="visual-styles.html">visual styles</a> before combining an SEM surface, a TEM interior and living brightfield motion in the same image.</p>')
    page('04-cells.html','The small-cell neighborhood.','Scale band 04 · small flagellates, algae & microbial context','At tens of micrometres, light direction, surface contact and invisible chemical gradients can matter more than familiar terrain.',body,('03-protists.html','Large single cells'),('environments.html','Compare habitats'))


def build_environments():
    body = section('Four environmental readings.', table(['Setting', 'Plausible inhabitants / scale', 'Visual ingredients', 'Possible environmental pressure'], [
        ('Moss and leaf litter', 'Selected soil/moss mites; wet recesses may host micro-animals.', 'Overlapping leaves, mineral grains, hyphae, wet and dry interfaces.', 'Humidity refuges, obstructed routes and changing surface traction.'),
        ('Moss water films', 'Tardigrades, bdelloid rotifers and some protists, depending on sample.', 'Leaf-cell walls, narrow menisci, trapped detritus and shallow water gaps.', 'Hydration, attachment and disconnection as water recedes.'),
        ('Freshwater pond margin / periphyton', 'Ciliates, amoebae, algae and attached feeders in suitable conditions.', 'Algal filaments, detrital flakes, biofilm-coated surfaces and open water pockets.', 'Food patchiness, flow exposure and available attachment sites.'),
        ('Biofilm-coated particle', 'Microbial assemblages, small grazers and selected surface-attached cells.', 'Irregular matrix, embedded cells and pores; not a smooth gelatin cube.', 'Species-specific access to resources and spatial chemistry.')
    ], 'Candidate settings, not verified species assemblages or prescribed game regions.') + '<p>The organism guides document wet habitats and selected morphology, while the soil-feeding review helps distinguish ecological roles. Actual coexistence still requires a site-specific sample record.' + cite('S02','S23') + '</p>')
    body += section('Use the material at its own scale.', refs('moss','spirogyra','vorticella','biofilm-sem'))
    body += section('Water is geometry as well as motion.', '<div class="split"><div><h3>Surface, film, volume</h3><p>A partly wet leaf offers exposed surface routes and submerged routes. A film has a thickness, a connected footprint and an interface; those should not collapse into one generic “wetness” value.</p><p>In an open pocket, swimmers can move above attached organisms. In a thin film, nearby walls and the air–water boundary alter motion. In a coverslipped sample, the glass is another real boundary. Representing one thin plane is a useful approximation only when the chosen habitat justifies it.</p></div><div><h3>Environmental change</h3><p>Evaporation can narrow connections and change solute concentrations; rewetting can reconnect patches and redistribute particles. These are plausible dynamics to investigate rather than specified timed hazards.</p><p>The position of an air–water interface is different from a current or a diffuse chemical field. A believable visual treatment should distinguish those phenomena.</p></div></div>')
    body += section('Four physical checks.', table(['Principle', 'Implication for a simulation study', 'What to avoid'], [
        ('Re = ρUL / μ', 'For a 50 µm body at 100 µm/s in water, using ρ≈1000 kg/m³ and μ≈0.001 Pa·s, Re≈0.005. This illustrative calculation suggests drag-dominated motion.', 'Applying the same regime to every mite, film, surface and flow without checking U and L.'),
        ('Diffusion time scales as length squared', 'Under the same diffusion coefficient, a route ten times longer takes roughly one hundred times as long to diffuse across.', 'A chemical trail that instantly updates throughout a large scene.'),
        ('Low inertia is not zero ambient flow', 'Organisms can be advected even when their own swimming has little momentum.', 'Long swimming coast after propulsion stops, or treating every vortex as a turbulent whirlpool.'),
        ('Geometry controls access', 'Pore width, body thickness and contact surfaces constrain passage independently of drawn screen size.', 'Allowing an opaque 3D body to pass through a gap just because the 2D outlines overlap.')
    ], 'Equations and examples are illustrative modeling notes, not measured parameters for the concept boards.') + '<p>The fluid-mechanics review supports the low-Reynolds-number interpretation. A surface crawler additionally needs adhesion and deformation; swimming equations alone do not model amoeboid movement.' + cite('S15') + '</p>')
    body += section('Chemistry is usually invisible.', '<p>Biofilms can develop internal resource gradients because metabolism and transport interact. An oxygen-poor region should not automatically be rendered as black poison fog. A scientific overlay could use isolines, arrows or a separate color channel, with an explicit label distinguishing data from optical appearance.' + cite('S16') + '</p><p>To assess a future scene, ask what organisms actually occur together, the water chemistry and temperature, the physical size of each gap, and how the image was acquired. Marine reference textures in this atlas remain labeled analogues. <a href="sources.html#image-rights">Image provenance and licenses</a> make those distinctions inspectable.</p>')
    page('environments.html','The environment is alive.','Habitat & physics notes','Moss films, freshwater detritus and biofilms offer different structures, transport processes and ecological pressures at the same apparent magnification.',body,('04-cells.html','Small cells'),('visual-styles.html','Compare visual styles'))


def build_styles():
    body = callout('Three meanings of realism', '<strong>Instrument realism</strong> reproduces how a microscope forms an image. <strong>Biological realism</strong> preserves anatomy, behavior and scale. <strong>Hypothetical scene realism</strong> imagines light interacting with that world from an immersive viewpoint. These can support each other, but none automatically guarantees the others.')
    body += section('Compare the visual languages.', table(['Treatment', 'What it reveals / looks like', '2D reading', '3D interpretation / caveat'], [
        ('Stereo / reflected light', 'Opaque cuticle, bristles, moss edges, earthy pigments and contact shadows.', 'Overhead surface navigation with mild depth cues.', 'A strong basis for immersive mites; use restrained macro-like reflected light.'),
        ('Transmitted brightfield', 'Pale background; weakly contrasting cytoplasm, pigmented material and dark edges.', 'A convincing wet-mount field with transparent overlapping bodies.', 'Requires a virtual transmitted-light image formation step; ordinary surface shading alone will not reproduce it.'),
        ('Phase contrast', 'Transparent bodies become legible; characteristic halos may appear.', 'Useful for small cells and movement without staining.', 'Halos should follow image formation, not act as permanent physical shells around objects.'),
        ('Differential interference contrast', 'Directional light/dark edges, apparent relief and internal optical differences.', 'Readable transparent anatomy without opaque monster textures.', 'Pseudo-relief follows optical-path gradients; it is not a geometric normal map.'),
        ('Darkfield', 'Dark background with bright scattering edges and particles.', 'Clear silhouettes; avoid making every particle equally intense.', 'A style can be simulated from 3D geometry, but edge brightness does not mean bioluminescence.'),
        ('Fluorescence / confocal', 'Selected emitters or labeled structures against dark backgrounds; often channel-colored.', 'Can isolate data or make a layer visible.', 'Requires an explicit fluorescent marker or autofluorescence basis. False color is a mapping, not ordinary material color.'),
        ('Hypothetical plausible visible-light immersion', 'Ambient illumination, pigment absorption, transmission and surface scattering.', 'A top-down or shallow oblique render can favor spatial clarity.', 'An imagined viewpoint. Light should not invent opaque interiors, glowing membranes or molecular visibility.'),
        ('SEM-inspired', 'Usually grayscale, highly textured surface detail and strong depth cues; optional false color.', 'A legible surface atlas or inspection view.', 'Living motion in this look is a deliberate hybrid; conventional specimens are prepared for vacuum.'),
        ('TEM-inspired', 'Thin-section internal ultrastructure; grayscale densities rather than whole living surfaces.', 'Could inform a scientific cutaway or sectional reference.', 'Not a substitute for a navigable intact environment. Separate preparation and section thickness from organism size.')
    ], 'Appearance notes are visual research, not a requirement to build every rendering mode.'))
    body += section('Optics constrain what can be seen.', '<p>Higher magnification does not by itself resolve smaller structures. Numerical aperture, wavelength, acquisition and contrast determine what information survives. Depth of field can be very shallow at high NA; an entire thick animal and the background cannot all be equally sharp in one honest optical section.' + cite('S17','S18') + '</p><p>DIC makes transparent bodies look sculpted by converting differences in optical path to contrast. Its apparent shadows are an imaging effect, not sunlight falling across tiny hills. Do not derive true height from that relief alone.' + cite('S19') + '</p><p>A game-like view might deliberately widen focus or exaggerate a boundary for readability. Label that compromise. Use selective emphasis and consistent material cues before resorting to a field full of hard outlines.</p>')
    body += section('Electron microscopes do not supply natural lighting.', '<p>Conventional SEM uses an electron beam and detected signals, not a miniature sun. Many biological samples are fixed, dehydrated and coated to remain stable and conductive in vacuum. Monochrome topography-like contrast is compelling, but it does not show the color or normal wet transparency of a living organism.' + cite('S20') + '</p><p>Cryo-SEM can preserve frozen hydrated material; environmental SEM is another exception to conventional dry preparation. These methods have their own conditions and artifacts, and do not establish that a normal SEM scene could host free swimming life. TEM commonly images thin prepared sections; the cited Paramecium dataset specifies approximately 75 nm resin sections.' + cite('S21','S22') + '</p>' + refs('tardigrade-sem','biofilm-sem'), 'electron')
    body += section('Concept boards, side by side.', concept('01-moss-frontier', ['Stereo-like observation','Immersive reflected light','SEM-inspired surface'], 'Mite-scale reflected lighting is the most familiar photographic option. Keep wetness local and body proportions grounded in reference.') + concept('02-waterfilm', ['DIC-inspired observation','Immersive film lighting','SEM-inspired specimen'], 'At micro-animal scale, transmitted contrast and hypothetical surface lighting reveal very different versions of the same body.') + concept('03-protist-garden', ['Brightfield observation','Immersive transparent bodies','Darkfield observation'], 'Large cells offer the clearest comparison of transparent interior, readable silhouette and scattering edge.') + concept('04-cell-neighborhood', ['Phase-contrast observation','Immersive small-cell view','SEM-inspired community'], 'At small-cell scale, preserve a large visual gap between a flagellate and its bacterial context. Exact pixel-to-micrometre calibration is absent from these paintings.'))
    body += section('How to use the paintings responsibly.', '<p>All four boards are generated visual hypotheses, saved locally as WebP. No web reference image was supplied as an edit target; the text prompts describe the scenes independently. The <a href="assets/concepts/prompts.json">saved prompt set</a> records the brief and tool.</p><p><strong>Known conceptual departures:</strong> cilia and flagella are enhanced; transparent bodies have more contrast than many live brightfield specimens; the water-film board dramatizes menisci and may imply incorrect film thickness; perspective panels are imagined rather than reconstructions. The mite’s first panel mixes optical cues. Generated legs, claws, organs and shell pores must be checked against the real references before modeling; the tardigrade must have exactly four leg pairs.</p><p>The panels are not calibrated images, taxonomic identifications or evidence of co-occurrence. Use them to compare mood, spatial readability and material treatment. Use reference micrographs and living footage to establish morphology, motion and measurements.</p>', 'art-caveats')
    body += section('2D and 3D are spatial choices, not styles.', '<p>A 2D simulation could use real microscope-like contrast, a painted environment, or an image rendered from 3D geometry. A 3D simulation could still present a fixed microscope camera. Separate dimensionality of movement, geometry used for rendering, camera freedom and the optical treatment.</p><p>Shallow layers may suit water films; full 3D may be valuable around filaments or in pore spaces. A readable fixed view can communicate biology more clearly than unrestricted camera movement. These are comparison points, not a selected presentation for a game.</p>')
    page('visual-styles.html','Different ways of seeing.','Visual research · optics & interpretation','A microscope view, a physically motivated immersive rendering and an electron-image treatment can each look realistic while making different claims.',body,('environments.html','Habitats'),('powers.html','Powers and dynamics'))


def build_powers():
    body = callout('Possibility space, not a game design', 'The entries below are interaction hypotheses. They do not select a protagonist, prescribe goals, define a progression system, balance statistics or assemble a game loop. Every “power” should retain a cost, a physical requirement and an honest distinction between evidence and invention.')
    rows = [
        ('Grip / bridge', 'Mite legs or tardigrade claws', 'Choose a viable contact path, hold a surface, cross a small discontinuity.', 'Body reach, footing and hydration; no universal wall climbing.', 'Foot placement / contact points', 'S01','S02'),
        ('Deform / squeeze', 'Amoeboid pseudopods and streaming', 'Redistribute body material to probe or pass a constrained route.', 'Approximate volume and contact area; a narrow route can be costly rather than freely passable.', 'Contour in 2D / bulk in 3D', 'S04','S06'),
        ('Engulf / retain', 'Amoeba food-cup formation', 'Surround an appropriate particle or prey and maintain capture geometry.', 'Target size, membrane contact and digestion time; not remote absorption.', 'Closing rim / captured volume', 'S05',None),
        ('Reverse / reorient', 'Paramecium ciliary reversal', 'Back away from an obstacle, change heading and resume movement.', 'A short organized response; retain directionality instead of an omnidirectional dash.', 'Ciliary wave / trajectory', 'S08',None),
        ('Discharge / escape', 'Paramecium trichocyst exocytosis', 'A short defensive displacement during a dangerous local encounter.', 'Experimental context supports escape; arbitrary range, aim and recharge are inventions.', 'Brief local discharge', 'S09',None),
        ('Anchor / retract', 'Vorticella contractile stalk', 'Withdraw rapidly toward a fixed attachment site and re-extend.', 'Tether geometry; reduced reach during withdrawal; no moving anchor.', 'Coiling stalk / extension', 'S10','S11'),
        ('Filter / intercept', 'Rotifer coronal cilia', 'Settle where particle transport makes feeding possible.', 'Suitable food, attachment and flow; not every micro-animal is a filter feeder.', 'Tracer particles / crown motion', 'S23',None),
        ('Sense / orient', 'Euglena phototaxis', 'Move toward a favorable illumination range and away from excessive exposure.', 'Directional response without image-forming vision; parameterize by species and conditions.', 'Light direction / separate data overlay', 'S13',None),
        ('Adhere / glide', 'Raphid pennate diatom motility', 'Navigate by changing substrate contact and secretion-driven traction.', 'Requires a suitable surface and the relevant organism; no generic rocket drive.', 'Slow relative movement / contact trace', 'S14',None),
        ('Suspend / recover', 'Tardigrade desiccation response', 'Trade present activity for persistence through loss of a wet connection.', 'Species-specific survival, inactive period and recovery; no active invulnerability.', 'Shrinking body / changing hydration', 'S02','S03'),
        ('Find a resource window', 'Biofilm chemical heterogeneity', 'Compare exposed access with sheltered but depleted interiors.', 'Fields can differ by chemistry; visibility needs an explicit scientific overlay.', 'Data layer / habitat geometry', 'S16',None),
    ]
    body += section('A vocabulary of biological powers.', table(['Power vocabulary', 'Observed basis', 'Possible interaction', 'Cost or boundary', 'Useful visual cue'], [(a,b+cite(*[x for x in (s,t) if x]),c,d,e) for a,b,c,d,e,s,t in rows], 'Every third-column entry is speculative, even when its biological basis is well documented.'))
    body += section('Dynamics that could emerge from combinations.', '<div class="grid"><article class="card"><h3>Attachment versus access</h3><p>A fixed feeder has a stable position but a limited feeding reach. A mobile cell can find other patches but must keep propelling or maintaining contact. This could make location meaningful without territorial behavior being assumed.</p><span class="tag idea">Spatial tradeoff</span></article><article class="card"><h3>Changing shape versus moving fast</h3><p>An amoeba’s body can wrap a surface while a ciliate moves around it. The contrast suggests different responses to the same gap, rather than a single movement controller with different speed values.</p><span class="tag idea">Movement contrast</span></article><article class="card"><h3>Wet connection versus dormant refuge</h3><p>A receding film could disconnect food patches. Remaining active, finding a wetter recess and entering an inactive state imply distinct outcomes; none should be treated as a universally superior action.</p><span class="tag idea">Habitat change</span></article><article class="card"><h3>Feeding creates transport</h3><p>Suspended particles can reveal a local current, and an attached organism can change what moves nearby. Neighbor interactions could follow from local transport without granting control of the entire fluid.</p><span class="tag idea">Local environmental coupling</span></article></div>')
    body += section('Time is another scale to keep honest.', '<p>A ciliary avoidance response, slow amoeboid reshaping, digestion, reproduction and survival through drying do not share one natural clock. A visualization can compress time, but should say which processes are accelerated and by how much. A cell dividing during an encounter is not a neutral substitute for a much slower population event.</p><p>Likewise, fluid drag, contact and response times do not become familiar animal inertia just because the camera is immersive. At low Reynolds number, sustained motion needs sustained propulsion, while ambient flow can still transport the organism.' + cite('S15') + '</p>')
    body += section('Avoid attractive but misleading powers.', '<ul><li><strong>Universal absorption:</strong> edible material, dissolved nutrients and large prey involve different uptake mechanisms.</li><li><strong>Magic light:</strong> fluorescence needs excitation and an emitting structure; chemical maps are explanatory data.</li><li><strong>Instant evolution:</strong> different species’ traits are not interchangeable upgrades on demand.</li><li><strong>Perfect radar:</strong> sensing can be local, noisy and modality-specific; an eyespot is not a camera.</li><li><strong>Tardigrade immunity:</strong> resistance depends on state, species and exposure conditions.</li><li><strong>Generic sticky water:</strong> quantify the scale and speed; include walls, interfaces and substrate attachment when relevant.</li></ul>')
    body += section('Questions that preserve room for invention.', '<p>Which trait is visually readable at the chosen field size? What physical substrate or resource does it require? What happens when that requirement disappears? Does it create a different relationship with the environment, or merely a bigger number? Would the same interaction read differently in a <a href="visual-styles.html">2D optical view and a 3D immersive one</a>?</p><p>Those questions can guide later experiments while leaving the actual game undesigned.</p>')
    page('powers.html','Powers already exist.','Gameplay research · affordances & constraints','Biology offers shape change, anchoring, sensing, feeding and dormancy. Their limitations may be as interesting as their effects.',body,('visual-styles.html','Visual styles'),('sources.html','Evidence and image credits'))


def build_sources():
    body = section('Evidence and confidence.', '<p>Research checked 30 October 2026. Technical and biological claims use institutional resources, primary studies, microscopy observations and research reviews. Source identifiers link back here from the reading pages. External sources require internet access; the atlas, art and imported images work offline.</p><p>Scale brackets organize the references for browsing; they are not universal species limits. Magnification examples assume stated optics. Paintings have no calibrated scale bars. Proposed interactions are original interpretations, not claims that animals plan or use powers in a human sense.</p><p>Important gaps remain: measured local coexistence, species-level diets and hydration limits, live motion sequences, calibrated sample depth and optical settings. The selected still images establish appearance, not a complete behavioral model.</p>')
    items = '<ol class="source-list">' + ''.join(f'<li id="{ident}"><span class="source-id">{ident} / {topic}</span><h3><a href="{esc(url)}">{title}</a></h3><p>{desc}</p></li>' for ident,topic,title,url,desc in SOURCES) + '</ol>'
    body += section('Research bibliography.', items, 'bibliography')
    body += section('Reference images &amp; individual rights.', '<p>The twelve selected images are downloaded into <code>assets/references/</code>. Each is credited below and beside its use. Creators retain their rights; the atlas does not relicense these images as a collection. CC BY-SA adaptations must follow their applicable share-alike terms. Commons thumbnails may reduce resolution; there are no additional crops, color changes or removed scale bars.</p><p>The <a href="assets/references/manifest.json">machine-readable manifest</a> includes source pages, original and downloaded URLs, creators, license links, access date, changes and SHA-256 checksums. Public-domain and CC0 status are reproduced from source declarations. An image license does not establish specimen identification or ecological coexistence.</p><p>Two context exceptions are intentional: Antarctic marine diatoms and marine seagrass biofilm are labeled morphology/material analogues. The source for the light-microscope tardigrade acknowledges phone-camera filtering. The Euglena reference has a strongly colored background; do not infer natural water color or a fully specified optical setup from it.</p>' + refs(*REFS.keys()), 'image-rights')
    body += section('Generated artwork and reproducibility.', '<p>Four original boards, each with three views, were made with the built-in image_gen tool from text prompts and saved as local WebP files. They are explicitly marked as AI concept art. The <a href="assets/concepts/prompts.json">prompt set</a> preserves the common brief and scene specifications. The actual artwork is linked on each scale page and in <a href="visual-styles.html#art-caveats">visual styles, with known caveats</a>.</p><p>Rebuild the static HTML with <code>python3 micro/research/build.py</code>. Refresh the image collection with <code>python3 micro/research/fetch_references.py</code> when network access is available; that refresh can update source metadata or source-file revisions. Open <a href="index.html">index.html</a> directly, or serve this directory with a basic local HTTP server. No framework, remote font or CDN is required.</p>')
    page('sources.html','Evidence &amp; image credits.','Research ledger · provenance & limits','Follow the source of a biological claim, inspect the rights of an imported image, and distinguish reference evidence from generated visual interpretation.',body,('powers.html','Powers and dynamics'),('index.html','Return to overview'))


if __name__ == '__main__':
    for build in (build_index, build_mites, build_waterfilm, build_protists, build_cells, build_environments, build_styles, build_powers, build_sources):
        build()
    print('Built 9 linked HTML research pages.')
